import itertools


def to_frames(segments, step=0.1, end=8.0):
    frames = [None] * int(round(end / step))
    for speaker, start, stop in segments:
        for index in range(int(round(start / step)), int(round(stop / step))):
            if 0 <= index < len(frames):
                frames[index] = speaker
    return frames


def best_mapping(reference, hypothesis):
    ref_labels = sorted({label for label in reference if label is not None})
    hyp_labels = sorted({label for label in hypothesis if label is not None})
    if not hyp_labels:
        return {}
    best = None
    for chosen in itertools.permutations(ref_labels, min(len(ref_labels),
                                                         len(hyp_labels))):
        mapping = dict(zip(hyp_labels, chosen))
        agreed = sum(1 for r, h in zip(reference, hypothesis)
                     if r is not None and h is not None and mapping.get(h) == r)
        if best is None or agreed > best[0]:
            best = (agreed, mapping)
    return best[1]


def der(reference, hypothesis, step=0.1, end=8.0):
    ref_frames = to_frames(reference, step, end)
    hyp_frames = to_frames(hypothesis, step, end)
    mapping = best_mapping(ref_frames, hyp_frames)
    total = sum(1 for label in ref_frames if label is not None)
    if total == 0:
        raise ValueError("the reference contains no speech")
    missed = false_alarm = confusion = 0
    for ref, hyp in zip(ref_frames, hyp_frames):
        if ref is not None and hyp is None:
            missed += 1
        elif ref is None and hyp is not None:
            false_alarm += 1
        elif ref is not None and mapping.get(hyp) != ref:
            confusion += 1
    errors = missed + false_alarm + confusion
    return {"total": total, "missed": missed, "false_alarm": false_alarm,
            "confusion": confusion, "der": errors / total, "mapping": mapping}


def write_rttm(segments, uri="file"):
    lines = []
    for speaker, start, stop in segments:
        lines.append(
            f"SPEAKER {uri} 1 {start:.3f} {stop - start:.3f} <NA> <NA> "
            f"{speaker} <NA> <NA>")
    return "\n".join(lines)


def parse_rttm(text):
    segments = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = line.split()
        if fields[0] != "SPEAKER" or len(fields) < 8:
            raise ValueError(f"not a speaker line: {line!r}")
        start = float(fields[3])
        duration = float(fields[4])
        segments.append((fields[7], start, start + duration))
    return segments
